package android.os; public class Handler {public static final java.util.concurrent.ScheduledExecutorService LOOP=java.util.concurrent.Executors.newSingleThreadScheduledExecutor();public Handler(Looper l){} public boolean post(Runnable r){LOOP.execute(r);return true;}public boolean postDelayed(Runnable r,long ms){LOOP.schedule(r,ms,java.util.concurrent.TimeUnit.MILLISECONDS);return true;}}
